using System;

[AttributeUsage(AttributeTargets.All, AllowMultiple = true)]
class A : Attribute { public A(string s) { } }

partial class C
{
    [A(nameof(p1))]
    [A(nameof(p2))] // 1
    partial C(
        [A(nameof(p1))] // 2
        [A(nameof(p2))]
        int p1);

    [A(nameof(p1))]
    [A(nameof(p2))] // 3
    partial C(
        [A(nameof(p1))] // 4
        [A(nameof(p2))]
        int p2)
    {
        Console.WriteLine(nameof(p1)); // 5
        Console.WriteLine(nameof(p2));
    }
}

